import React, { useRef } from 'react';
import { Menu } from 'primereact/menu';
import { Toast } from 'primereact/toast';
import { Button } from 'primereact/button';

export default function Popup() {
    const menuLeft = useRef(null);
    const menuRight = useRef(null);
    const toast = useRef(null);
    const items = [
        {
            label: 'Options',
            items: [
                {
                    label: 'Refresh',
                    icon: 'pi pi-refresh'
                },
                {
                    label: 'Export',
                    icon: 'pi pi-upload'
                },
                {
                    label: 'Custom template',
                    template: (item, options) => {
                        return (
                            <div className="menu-item-link" data-pc-section="content" onMouseMove={(e) => options.onMouseMove(e)}>
                                <a href="#" className="menu-action">
                                    Lorem ipsum
                                </a>
                            </div>
                        );
                    }
                }
            ]
        }
    ];

    return (
        <>
            <Toast ref={toast}></Toast>
            <Menu model={items} popup ref={menuLeft} id="popup_menu_left" />
            <Button className="mgr4" label="Show Left" icon="pi pi-align-left" onClick={(event) => menuLeft.current.toggle(event)} aria-controls="popup_menu_left" aria-haspopup />
            <Menu model={items} popup ref={menuRight} id="popup_menu_right" popupAlignment="right" />
            <Button label="Show Right" icon="pi pi-align-right" onClick={(event) => menuRight.current.toggle(event)} aria-controls="popup_menu_right" aria-haspopup />
        </>
    )

}